package ru.livingvillages;

import org.junit.jupiter.api.Test;
import ru.livingvillages.domain.*;
import ru.livingvillages.persistence.Database;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class RoutinesTest {
    @Test void restTargetsAreOnTheFloorBeyondTheBedFootForEveryOrientation() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var hall=v.buildings.getFirst();var resident=v.residents.getFirst();resident.home=hall.id;var p=v.projects.stream().filter(q->q.building.equals(hall.id)).findFirst().orElseThrow();p.blocks.clear();var directions=Map.of("north",new int[]{0,1},"south",new int[]{0,-1},"east",new int[]{-1,0},"west",new int[]{1,0});for(var entry:directions.entrySet()){p.blocks.clear();p.blocks.add(new Village.Block(10,65,20,4,"minecraft:air","minecraft:red_bed[facing="+entry.getKey()+",part=foot]","RED_BED"));var target=Routines.plan(v,resident,18000,0,rules,false);assertEquals(10+entry.getValue()[0],target.x());assertEquals(20+entry.getValue()[1],target.z());assertEquals(65,target.y());}}
    @Test void farmerGoesToTheRealFieldAndMerchantKeepsHisOwnWorkplace() throws Exception {var v=AutonomyData.village();var r=AutonomyData.rules();var farmer=v.residents.get(2);var farm=v.buildings.get(1);farm.x=20;farm.workX=21;farm.workY=65;var plan=v.projects.stream().filter(p->p.building.equals(farm.id)).findFirst().orElseThrow();plan.blocks.add(new Village.Block(26,65,3,2,"minecraft:air","minecraft:carrots[age=7]","CARROT"));var target=Routines.plan(v,farmer,3000,0,r,false);assertEquals(Routines.Activity.WORK,target.activity());assertEquals(26,target.x());assertEquals(3,target.z());var store=AutonomyData.building(v,"warehouse",null);store.workX=-18;v.residents.get(1).workplace=store.id;assertEquals(Routines.Activity.TRADE,Routines.plan(v,v.residents.get(1),3000,0,r,false).activity());assertEquals(-18,Routines.plan(v,v.residents.get(1),3000,0,r,false).x());}
    @Test void nightAndDangerUseAssignedHousingWithoutChangingEconomy() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var hall=v.buildings.getFirst();for(var r:v.residents)r.home=hall.id;var farmer=v.residents.get(2);var stock=new TreeMap<>(v.stock.items);assertEquals(hall.id,Routines.plan(v,farmer,18000,0,rules,false).building());assertEquals(Routines.Activity.REST,Routines.plan(v,farmer,18000,0,rules,false).activity());assertEquals(Routines.Activity.SHELTER,Routines.plan(v,farmer,3000,0,rules,true).activity());assertEquals(stock,v.stock.items);assertEquals(0,v.days);assertEquals(1024,v.treasury);}
    @Test void homesAndIdleDestinationsAreSpreadAndStable() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();v.buildings.getFirst().x=-20;for(var person:v.residents)person.home=v.buildings.getFirst().id;var a=Routines.plan(v,v.residents.get(0),18000,0,rules,false);var b=Routines.plan(v,v.residents.get(1),18000,0,rules,false);assertNotEquals(a,b);assertEquals(a,Routines.plan(v,v.residents.get(0),18001,12,rules,false));var child=v.residents.get(2);child.matureDay=10;assertEquals(Routines.Activity.PLAY,Routines.plan(v,child,3000,0,rules,false).activity());}
    @Test void craftingDoesNotStealThePermanentProducerAssignment() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();v.days=1;v.stock.add("OAK_LOG",32,v.capacity);var order=new Village.Project();order.building=v.buildings.getFirst().id;order.required.put("OAK_PLANKS",64);v.projects.add(order);var pit=AutonomyData.building(v,"stone_pit","stone_pit");var worker=v.residents.get(1);worker.workplace=pit.id;Assembly.day(v,rules);assertEquals(pit.id,worker.workplace);assertNotNull(worker.craftWorkplace);assertEquals(v.days,worker.craftDay);assertEquals(Routines.Activity.CRAFT,Routines.plan(v,worker,5500,0,rules,false).activity());assertEquals(pit.id,Routines.plan(v,worker,7000,0,rules,false).building());var saved=Database.copy(v).resident(worker.id);assertEquals(worker.craftWorkplace,saved.craftWorkplace);assertEquals(pit.id,saved.workplace);}
    @Test void guardsPatrolRoadsAndBuildersGoToAnActualProject() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var road=new Village.Project();road.state="COMPLETE";road.blocks.add(new Village.Block(18,64,7,5,"minecraft:air","minecraft:dirt_path",null));v.projects.add(road);var guard=v.residents.getLast();var target=Routines.plan(v,guard,18000,0,rules,false);assertEquals(Routines.Activity.PATROL,target.activity());assertEquals(18,target.x());var p=new Village.Project();p.building=v.buildings.get(1).id;p.state="QUEUED";v.projects.add(p);assertEquals(Routines.Activity.BUILD,Routines.plan(v,v.residents.getFirst(),3000,0,rules,false).activity());}
    @Test void corruptPositionsCannotBecomeSpawnLocations(){assertFalse(new Village.Position(Double.NaN,64,0,0).valid());assertFalse(new Village.Position(0,Double.POSITIVE_INFINITY,0,0).valid());var v=new Village();var resident=new Village.Resident();resident.position=new Village.Position(-12.4,65,23.8,72);v.residents.add(resident);var loaded=Database.copy(v);assertEquals(-12.4,loaded.residents.getFirst().position.x);assertEquals(72,loaded.residents.getFirst().position.yaw);}
    @Test void plannedWorkplaceDoesNotTurnTheOnlyBuilderIntoAnotherFarmer() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var farm=v.buildings.get(1);farm.complete=false;var p=v.projects.stream().filter(q->q.building.equals(farm.id)).findFirst().orElseThrow();p.state="BUILDING";Jobs.reconcile(v,rules);assertEquals(farm.id,v.residents.get(2).workplace);assertEquals(Village.Role.FARMER,v.residents.get(2).role);}
    @Test void unsupportedPreFreeFormatsAreRejectedWithoutModifyingTheSource(){var v=new Village();v.format=6;var r=new Village.Resident();r.alive=false;v.residents.add(r);assertThrows(IllegalStateException.class,()->Database.copy(v));assertFalse(v.residents.getFirst().alive);assertEquals(6,v.format);}
}
